def hasCycle(head, pos):
    if not head or pos == -1:
        return False
    class Node:
        def __init__(self, val):
            self.val = val
            self.next = None
    nodes = [Node(x) for x in head]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
    if pos >= 0 and pos < len(nodes):
        nodes[-1].next = nodes[pos]
    slow = fast = nodes[0]
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

